mapper.select:
select id, stock_code, stock_name, free_date, free_shares, lift_market_cap,
       free_ratio, total_ratio, shares_type, holder_num, source, create_time, update_time
from stock_lockup_schedule
where free_date >= #{start}
  and free_date <= #{end}
order by free_date asc, stock_code asc

select distinct stock_code
from stock_lockup_schedule
where free_date >= #{start}
  and free_date <= #{end}
  and free_ratio >= #{minRatio}
